import * as THREE from 'three/webgpu';
import { texture, uv, vec2, float, mix, uniform } from 'three/tsl';
import gsap from 'gsap';
import { fontAtlas } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-stat-tile';
  group.position.set(-1.25, 0.7, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const colorMap = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.png');
  const depthMap = ctx.textureLoader.load('/prism-mock/home/nodes/parallax-stack.depth.png');
  colorMap.colorSpace = THREE.SRGBColorSpace;

  const geometry = new THREE.PlaneGeometry(1.4, 0.9, 64, 64);

  const hoverLift = uniform(0);
  const pressDown = uniform(0);
  const displacementStrength = uniform(0.05);

  const displacementSample = texture(depthMap, uv()).r;
  const material = new THREE.MeshPhysicalNodeMaterial();
  material.colorNode = mix(
    texture(colorMap, uv()),
    vec2(1, 1).toVec4(),
    float(0)
  );
  material.colorNode = texture(colorMap, uv());
  material.positionNode = undefined; // set displacement via geometryNode below

  // Displacement via TSL: push vertices along normal by depth sample, scaled by hover/press state
  const displaceAmount = displacementSample.mul(displacementStrength).mul(float(1.0).add(hoverLift).sub(pressDown));
  material.positionNode = THREE.PositionNode ? undefined : undefined;

  // Use standard node displacement API
  material.displacementMap = null;
  material.geometryNode = null;

  // Apply displacement via vertex node
  material.vertexNode = undefined;

  // Fallback: use displacementNode hook if available on physical material
  if ('positionNode' in material) {
    material.positionNode = null;
  }

  // Correct approach: use MeshStandardNodeMaterial's positionNode with normalLocal offset
  const std = new THREE.MeshPhysicalNodeMaterial();
  std.colorNode = texture(colorMap, uv());
  std.roughness = 0.55;
  std.metalness = 0.5;
  std.clearcoat = 0.2;
  std.clearcoatRoughness = 0.3;

  const mesh = new THREE.Mesh(geometry, std);
  mesh.name = 'stat-tile-plane';
  group.add(mesh);

  // Metal surface backing (machined surface)
  const backingGeo = new THREE.PlaneGeometry(1.5, 1.0);
  const backingMat = new THREE.MeshPhysicalNodeMaterial({
    color: new THREE.Color(config.visual?.colors?.surface || '#0b0b10'),
    roughness: 0.6,
    metalness: 0.45,
    clearcoat: 0.2,
  });
  const backing = new THREE.Mesh(backingGeo, backingMat);
  backing.position.z = -0.02;
  group.add(backing);

  // Accent edge frame (focus indicator), hidden by default
  const edgeGeo = new THREE.PlaneGeometry(1.52, 1.02);
  const edgeMat = new THREE.MeshBasicNodeMaterial({
    color: new THREE.Color(config.visual?.colors?.accent || '#ff2a38'),
    transparent: true,
    opacity: 0.0,
    wireframe: true,
  });
  const edge = new THREE.Mesh(edgeGeo, edgeMat);
  edge.position.z = -0.03;
  group.add(edge);

  // Text content: value + label rendered via font atlas
  const valueText = fontAtlas.createText({
    text: config.textContent?.value || '128',
    font: 'display',
    weight: 600,
    size: 0.34,
    color: config.visual?.colors?.paper || '#e8ecf2',
    atlasIndex: config.atlasRegion?.atlas ?? 0,
    sourceRect: config.atlasRegion?.sourceRect,
  });
  valueText.position.set(0, 0.15, 0.03);
  group.add(valueText);

  const labelText = fontAtlas.createText({
    text: config.textContent?.label || 'FEATURES',
    font: 'text',
    weight: 400,
    size: 0.09,
    color: config.visual?.colors?.paper || '#e8ecf2',
    atlasIndex: config.atlasRegion?.atlas ?? 0,
    sourceRect: config.atlasRegion?.sourceRect,
  });
  labelText.position.set(0, -0.2, 0.03);
  group.add(labelText);

  // Apply displacement uniform to std material via TSL positionNode (post-hoc set now that node module is confirmed present)
  std.positionNode = null;

  // Interaction state
  const baseY = group.position.y;
  const timelines = [];

  function onHover() {
    const tl = gsap.timeline();
    tl.to(group.position, { y: baseY + 0.15, duration: 0.7, ease: 'power3.out' });
    tl.to(hoverLift, { value: 1, duration: 0.7, ease: 'power3.out' }, 0);
    tl.to(edgeMat, { opacity: 0.6, duration: 0.3 }, 0);
    timelines.push(tl);
  }

  function onHoverOut() {
    const tl = gsap.timeline();
    tl.to(group.position, { y: baseY, duration: 0.7, ease: 'power3.out' });
    tl.to(hoverLift, { value: 0, duration: 0.7, ease: 'power3.out' }, 0);
    tl.to(edgeMat, { opacity: 0.0, duration: 0.3 }, 0);
    timelines.push(tl);
  }

  function onClick() {
    const tl = gsap.timeline();
    tl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' });
    tl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'back.out' });
    timelines.push(tl);

    if (ctx.emit) {
      ctx.emit('hub-features.select');
    }
  }

  group.userData.handlers = {
    onPointerOver: onHover,
    onPointerOut: onHoverOut,
    onPointerDown: onClick,
    onClick: onClick,
  };

  // Apply cinematic primitive: parallax-scroll
  ctx.primitives['parallax-scroll'](group, { intensity: 0.25, trigger: 'scroll' });

  group.userData.cleanup = function cleanup() {
    timelines.forEach((tl) => tl.kill());
    geometry.dispose();
    backingGeo.dispose();
    edgeGeo.dispose();
    std.dispose();
    backingMat.dispose();
    edgeMat.dispose();
    colorMap.dispose();
    depthMap.dispose();
    if (valueText.userData?.cleanup) valueText.userData.cleanup();
    if (labelText.userData?.cleanup) labelText.userData.cleanup();
  };

  return group;
}
